(function(){
  function cls(n){ try { return Java.loadClass(n); } catch (e) { return java.lang.Class.forName(n); } }
  var BR = cls("net.minecraft.core.registries.BuiltInRegistries");
  var RL = cls("net.minecraft.resources.ResourceLocation");
  var S = cls("net.minecraft.world.item.ItemStack");
  var CuriosApi = cls("com.merlinkitsune.astral_dice.compat.curios.CuriosApi");
  var Dice = cls("com.merlinkitsune.astral_dice.item.dice.DiceCurioItem");
  var player = AutoJS.players()[0];
  function stack(id){ return new S(BR.ITEM.get(RL.parse(id))); }
  function idOf(st){ return (st == null || st.isEmpty()) ? "" : String(BR.ITEM.getKey(st.getItem())); }
  var keys = [];
  var kit = CuriosApi.getCuriosMap(player).keySet().iterator();
  while (kit.hasNext()) { keys.push(String(kit.next())); }
  var out = { keys: keys };
  function has(n){ for (var i=0;i<keys.length;i++){ var k=keys[i]; if (k===n || k.indexOf("/"+n)>=0) return true; } return false; }
  out.hasDiceSlot = has("dice"); out.hasStandSlot = has("stand"); out.hasChipSlot = has("chip");
  function h(name){ var o = CuriosApi.getStacksHandler(player, name); return (o != null && o.isPresent()) ? o.get() : null; }
  var hd = h("dice"), hs = h("stand"), hc = h("chip");
  out.diceHandler = hd != null; out.standHandler = hs != null; out.chipHandler = hc != null;
  if (hd == null || hs == null || hc == null) { out.abort = true; return out; }
  out.abort = false;
  hd.getStacks().setStackInSlot(0, S.EMPTY);
  hs.getStacks().setStackInSlot(0, S.EMPTY);
  Dice.enforceNoDiceState(player);
  out.diceBase = hd.getSlots();
  out.standBase = hs.getSlots();
  out.chipBase = hc.getSlots();
  function refresh(){ Dice.refreshChipSlotCount(player); return hc.getSlots(); }
  function equipDice(id){ hd.getStacks().setStackInSlot(0, stack(id)); return refresh(); }
  out.chipNoDice = refresh();
  out.chipGolden = equipDice("astral_dice:golden_dice");
  out.chipDiamond = equipDice("astral_dice:diamond_dice");
  out.chipNetherite = equipDice("astral_dice:netherite_dice");
  out.chipNetherStar = equipDice("astral_dice:nether_star_dice");
  hc.getStacks().setStackInSlot(0, stack("astral_dice:flashlight_chip"));
  out.chipItemReadback = idOf(hc.getStacks().getStackInSlot(0));
  hc.getStacks().setStackInSlot(0, S.EMPTY);
  hs.getStacks().setStackInSlot(0, stack("astral_dice:parunan_sign"));
  out.standItemReadback = idOf(hs.getStacks().getStackInSlot(0));
  hs.getStacks().setStackInSlot(0, S.EMPTY);
  hd.getStacks().setStackInSlot(0, S.EMPTY);
  Dice.enforceNoDiceState(player);
  out.chipTeardown = hc.getSlots();
  out.diceTeardown = idOf(hd.getStacks().getStackInSlot(0));
  out.standTeardown = idOf(hs.getStacks().getStackInSlot(0));
  return out;
})()
